def evaluate(current_reputation, observation, my_history, round_num):
    action = observation['action']
    target = 1.0 if action == 'cooperate' else -1.0

    # Base learning rate: start moderate, then increase to adapt to new patterns
    if round_num <= 10:
        alpha = 0.5
    else:
        alpha = 0.8

    # Increase learning rate when observed action contradicts current reputation
    if (current_reputation > 0.3 and action == 'defect') or \
       (current_reputation < -0.3 and action == 'cooperate'):
        alpha = min(1.0, alpha * 1.5)

    # Reduce learning rate if own recent actions are very consistent (cautious trust)
    if len(my_history) >= 3:
        recent_own = [entry['action'] for entry in my_history[-3:]]
        own_coop = sum(1 for a in recent_own if a == 'cooperate')
        if own_coop == 3 or own_coop == 0:
            alpha *= 0.7

    new_rep = (1 - alpha) * current_reputation + alpha * target
    return max(-1.0, min(1.0, new_rep))


def decide(recipient_reputation, round_num, my_history):
    # Base threshold: starts positive and declines slowly, floor at -0.3
    threshold = 0.3 - 0.05 * round_num
    threshold = max(-0.3, threshold)

    # Adjust threshold based on own recent behaviour (3-round window)
    if len(my_history) >= 3:
        last_three = [entry['action'] for entry in my_history[-3:]]
        coop_count = sum(1 for a in last_three if a == 'cooperate')
        # More forgiving if I cooperated in at least 2 of the last 3 rounds
        if coop_count >= 2:
            threshold -= 0.25
        # Less forgiving if I defected in at least 2 of the last 3 rounds
        if coop_count <= 1:
            threshold += 0.15

    # Increase threshold if I just defected in the last round (reluctance to be exploited)
    if len(my_history) >= 1:
        if my_history[-1]['action'] == 'defect':
            threshold += 0.2

    # Long-term adjustment: if overall cooperation rate is very low, become more cooperative
    if round_num > 10:
        coop_total = sum(1 for entry in my_history if entry['action'] == 'cooperate')
        if len(my_history) > 0 and coop_total / len(my_history) < 0.4:
            threshold -= 0.2

    return recipient_reputation >= threshold
